using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json;
public static class BEOCatalog {public static object Run(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);string dir="Assets/Afrer_Seconds/05.Model/Props/B4/";var rows=Directory.GetFiles(dir,"BX_*.fbx").Select(f=>{string p=f.Replace('\\','/');var src=AssetDatabase.LoadAssetAtPath<GameObject>(p);var g=UnityEngine.Object.Instantiate(src);g.hideFlags=HideFlags.HideAndDontSave;try{var rr=g.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr.Skip(1))b.Encapsulate(r.bounds);return new{name=src.name,asset=p,size=new[]{b.size.x,b.size.y,b.size.z},center=new[]{b.center.x,b.center.y,b.center.z}};}finally{UnityEngine.Object.DestroyImmediate(g);}}).ToArray();File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_ExperimentOperations/catalog.json")),JsonConvert.SerializeObject(rows,Formatting.Indented));return new{models=rows.Length};}}
